        if (null === $expFold) {
            return false;
        }
        static $high = [
            'seventieth' => true,
            'seventyfirst' => true,
            'seventysecond' => true,
            'seventythird' => true,
            'seventyfourth' => true,
            'seventyfifth' => true,
            'seventysixth' => true,
            'seventyseventh' => true,
            'seventyeighth' => true,
            'seventyninth' => true,
            'eightieth' => true,
            'eightyfirst' => true,
            'eightysecond' => true,
            'eightythird' => true,
            'eightyfourth' => true,
            'eightyfifth' => true,
            'eightysixth' => true,
            'eightyseventh' => true,
            'eightyeighth' => true,
            'eightyninth' => true,
            'ninetieth' => true,
        ];
        if (!isset($high[$expFold])) {
            return false;
